import fs from 'node:fs';
import path from 'node:path';
import type { ComplianceCountry } from './types';

/**
 * World geometry is generated by `scripts/build-world-map.mjs`
 * from Natural Earth (public domain) via world-atlas (© Mike Bostock, BSD-3-Clause).
 * 1:110m countries, plus 1:50m where 110m omits a state (for example Singapore).
 */
interface WorldCountry {
  id: string;
  d: string;
  cx: number;
  cy: number;
  x: number;
  y: number;
  w: number;
  h: number;
  small: boolean;
}

interface WorldFile {
  w: number;
  h: number;
  notice: string;
  sphere: string;
  graticule: string;
  countries: WorldCountry[];
}

const world = JSON.parse(
  fs.readFileSync(path.join(process.cwd(), 'src/data/world-countries.json'), 'utf8'),
) as WorldFile;

/** Site codes that are not already ISO 3166-1 alpha-2. */
const ISO_ALIAS: Record<string, string> = { uk: 'gb' };

/**
 * Member states drawn as one market when `eu.json` exists and that state
 * does not have its own compliance file. UK is a separate page.
 */
const EU_MEMBER_ISO = [
  'at', 'be', 'bg', 'hr', 'cy', 'cz', 'dk', 'ee', 'fi', 'fr', 'de', 'gr',
  'hu', 'ie', 'it', 'lv', 'lt', 'lu', 'mt', 'nl', 'pl', 'pt', 'ro', 'sk',
  'si', 'es', 'se',
] as const;

export interface ComplianceMapLink {
  cc: string;
  name: string;
  region: string;
  must: number;
  /** Projected outline. One market may be several countries (欧盟). */
  d: string;
  cx: number;
  cy: number;
  small: boolean;
  /** Padded viewBox to focus this market. */
  x: number;
  y: number;
  w: number;
  h: number;
  area: number;
}

export interface ComplianceMapRegion {
  id: string;
  x: number;
  y: number;
  w: number;
  h: number;
}

export interface ComplianceMapOff {
  cc: string;
  name: string;
  region: string;
  must: number;
}

export interface ComplianceMapModel {
  w: number;
  h: number;
  sphere: string;
  graticule: string;
  /** Countries with no compliance page, plus distant territories split off the main shape. */
  dim: string;
  links: ComplianceMapLink[];
  /** Compliance pages that have no country shape (still listed, not drawn as destinations). */
  offMap: ComplianceMapOff[];
  regions: ComplianceMapRegion[];
  note: string;
}

interface Box {
  x: number;
  y: number;
  w: number;
  h: number;
}

function isoForSite(cc: string): string {
  const key = cc.toLowerCase();
  return ISO_ALIAS[key] ?? key;
}

function round1(n: number): number {
  return Math.round(n * 10) / 10;
}

/** Fit a set of country boxes into a viewBox that matches the map aspect. */
function viewFor(boxes: Box[]): Box {
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const box of boxes) {
    if (box.w <= 0 || box.h <= 0) continue;
    minX = Math.min(minX, box.x);
    minY = Math.min(minY, box.y);
    maxX = Math.max(maxX, box.x + box.w);
    maxY = Math.max(maxY, box.y + box.h);
  }
  if (!Number.isFinite(minX)) return { x: 0, y: 0, w: world.w, h: world.h };
  const cx = (minX + maxX) / 2;
  const cy = (minY + maxY) / 2;
  let w = Math.max(maxX - minX, 72);
  let h = Math.max(maxY - minY, 72 * (world.h / world.w));
  w *= 1.5;
  h *= 1.5;
  const aspect = world.w / world.h;
  if (w / h < aspect) w = h * aspect;
  else h = w / aspect;
  w = Math.min(w, world.w);
  h = Math.min(h, world.h);
  if (w / h < aspect) w = Math.min(world.w, h * aspect);
  else h = Math.min(world.h, w / aspect);
  if (w >= world.w * 0.92 && h >= world.h * 0.92) return { x: 0, y: 0, w: world.w, h: world.h };
  const x = Math.min(Math.max(0, cx - w / 2), world.w - w);
  const y = Math.min(Math.max(0, cy - h / 2), world.h - h);
  return { x: round1(x), y: round1(y), w: round1(w), h: round1(h) };
}

interface Geometry {
  d: string;
  cx: number;
  cy: number;
  box: Box;
  small: boolean;
  area: number;
}

function geometryOf(parts: WorldCountry[]): Geometry | undefined {
  const drawn = parts.filter((part) => part.d);
  if (!drawn.length) return undefined;
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const part of drawn) {
    if (part.w <= 0 || part.h <= 0) continue;
    minX = Math.min(minX, part.x);
    minY = Math.min(minY, part.y);
    maxX = Math.max(maxX, part.x + part.w);
    maxY = Math.max(maxY, part.y + part.h);
  }
  const box = Number.isFinite(minX)
    ? { x: minX, y: minY, w: maxX - minX, h: maxY - minY }
    : { x: drawn[0]!.cx, y: drawn[0]!.cy, w: 0, h: 0 };
  const anchor = drawn.reduce((best, part) => (part.w * part.h > best.w * best.h ? part : best));
  return {
    d: drawn.map((part) => part.d).join(' '),
    cx: anchor.cx,
    cy: anchor.cy,
    box,
    small: drawn.length === 1 && drawn[0]!.small,
    area: Math.max(box.w * box.h, 0.01),
  };
}

function linkFrom(country: ComplianceCountry, geometry: Geometry): ComplianceMapLink {
  const view = viewFor([geometry.box]);
  return {
    cc: country.country,
    name: country.name_zh,
    region: country.region,
    must: country.items.filter((item) => item.mandatory).length,
    d: geometry.d,
    cx: geometry.cx,
    cy: geometry.cy,
    small: geometry.small,
    x: view.x,
    y: view.y,
    w: view.w,
    h: view.h,
    area: geometry.area,
  };
}

export function buildComplianceMap(countries: ComplianceCountry[]): ComplianceMapModel {
  const byId = new Map<string, WorldCountry[]>();
  for (const shape of world.countries) {
    if (!shape.id) continue;
    const list = byId.get(shape.id) ?? [];
    list.push(shape);
    byId.set(shape.id, list);
  }

  const used = new Set<string>();
  const links: ComplianceMapLink[] = [];
  const rawBoxes = new Map<string, Box[]>();

  for (const country of countries) {
    if (country.country === 'eu') continue;
    const iso = isoForSite(country.country);
    const geometry = geometryOf(byId.get(iso) ?? []);
    if (!geometry) continue;
    used.add(iso);
    links.push(linkFrom(country, geometry));
    const boxes = rawBoxes.get(country.region) ?? [];
    boxes.push(geometry.box);
    rawBoxes.set(country.region, boxes);
  }

  const eu = countries.find((country) => country.country === 'eu');
  if (eu) {
    const members = EU_MEMBER_ISO.filter((iso) => byId.has(iso) && !used.has(iso));
    const parts = members.flatMap((iso) => byId.get(iso) ?? []);
    const geometry = geometryOf(parts);
    if (geometry) {
      for (const iso of members) used.add(iso);
      const germany = byId.get('de')?.[0];
      if (germany) {
        geometry.cx = germany.cx;
        geometry.cy = germany.cy;
      }
      geometry.small = false;
      links.push(linkFrom(eu, geometry));
      const boxes = rawBoxes.get(eu.region) ?? [];
      boxes.push(geometry.box);
      rawBoxes.set(eu.region, boxes);
    }
  }

  const linked = new Set(links.map((link) => link.cc));
  const offMap: ComplianceMapOff[] = countries
    .filter((country) => !linked.has(country.country))
    .map((country) => ({
      cc: country.country,
      name: country.name_zh,
      region: country.region,
      must: country.items.filter((item) => item.mandatory).length,
    }));
  const regions: ComplianceMapRegion[] = [];
  for (const country of countries) {
    if (!linked.has(country.country) || regions.some((region) => region.id === country.region)) continue;
    const boxes = rawBoxes.get(country.region) ?? [];
    const view = viewFor(boxes);
    regions.push({ id: country.region, ...view });
  }

  const dim = world.countries
    .filter((shape) => !shape.id || !used.has(shape.id))
    .map((shape) => shape.d)
    .join(' ');

  const euName = eu && linked.has(eu.country) ? eu.name_zh : '';
  const note = euName
    ? `亮色区域可以进入该市场的合规页。欧盟成员国进入「${euName}」。暗色国家没有单独页面。地图边界来自 Natural Earth。`
    : '亮色区域可以进入该市场的合规页。暗色国家没有单独页面。地图边界来自 Natural Earth。';

  if (!links.length) throw new Error('合规地图没有可进入的市场');

  return {
    w: world.w,
    h: world.h,
    sphere: world.sphere,
    graticule: world.graticule,
    dim,
    links,
    offMap,
    regions,
    note,
  };
}
